using System;
using System.Collections.Generic;
using System.IO;
namespace BF4Bots {public static class LockerRepair {
 public static void Prepare(string root,Action<string> progress){string directory=Path.Combine(root,"Data\\Win32\\Levels\\MP\\MP_Prison");foreach(string file in new[]{"MP_Prison.toc","MP_Prison.sb"})if(!File.Exists(Path.Combine(directory,file))||new FileInfo(Path.Combine(directory,file)).Length==0)throw new FileNotFoundException("Arquivo necessário de Operation Locker ausente: "+file);var cfg=Settings.Read(root);int port=Int32.Parse(Settings.Get(cfg,"RconPort","25210"));string password=Settings.Get(cfg,"RconPassword","");OneClick.PrepareLocal(root,progress);using(var r=new Rcon()){r.Connect("127.0.0.1",port,password);var before=r.Maps();var target=MapNow.Exclusive(new RotationEntry{Map="MP_Prison",Mode="ConquestLarge0",Rounds=1});string backup=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"BF4BotLauncher","rotation-backups",DateTime.Now.ToString("yyyyMMdd-HHmmssfff")+"-locker-exclusivo.json");if(!Rcon.Same(before,target))LocalRotation.Save(root,r,before,target,backup);LocalRotation.SaveName(root,"Offline - Operation Locker");}progress("Atualizando o anúncio do servidor com somente Operation Locker…");var restart=Server.PrepareRestart(root);Server.Start(root,restart);OneClick.PrepareLocal(root,progress);using(var r=new Rcon()){r.Connect("127.0.0.1",port,password);var choice=new RotationEntry{Map="MP_Prison",Mode="ConquestLarge0",Rounds=1};MapNow.SwitchAndWait(r,choice,"Offline - Operation Locker");var current=r.Maps();if(current.Count!=1||current[0].Map!="MP_Prison")throw new IOException("A rotação exclusiva de Operation Locker não foi confirmada.");}OneClick.HideHelpers(root);string reports=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"BF4BotLauncher","reports");Directory.CreateDirectory(reports);File.WriteAllText(Path.Combine(reports,"locker-exclusive.txt"),"Arquivos MP_Prison.toc/sb presentes. Rotação persistida e ativa: somente MP_Prison ConquestLarge0 1. Servidor reiniciado e mapa/nome reconfirmados. Nenhum mapa XP/DLC na rotação anunciada.");}
}}
